'use strict';
// ============ 开发者模式 + 开发者工具（默认隐藏，更新日志彩蛋解锁） ============
let devMode = false;
const EX_DEV_KEY = 'ex_dev_mode';
try { devMode = localStorage.getItem(EX_DEV_KEY) === '1'; } catch (e) {}
let _clTarget = null, _clTime = 0, _clCycles = 0;

/* 彩蛋：开发者工具列表第一次展开时显示一张图而不是选项，第二次展开才显示选项。
   一次性 —— 展开过一次就写死 ex_dev_egg_seen，之后永远直接显示选项。 */
const EX_DEV_EGG_KEY = 'ex_dev_egg_seen';
function devEggSeen() { try { return localStorage.getItem(EX_DEV_EGG_KEY) === '1'; } catch (e) { return false; } }
function markDevEggSeen() { try { localStorage.setItem(EX_DEV_EGG_KEY, '1'); } catch (e) {} }

