/* ---- MC 结构（.mcstructure）导入导出入口：默认隐藏，开发者选项里可开 ----------------
   用户要求：结构导入/导出按钮平时不出现（它们属于「给 Minecraft 基岩版倒结构」的偏门功能，
   普通用户点了也用不上，还占着导入/导出面板的位置），只有在【开发者模式 → 🛠 开发者工具】
   里把开关打开后才显示。开关状态独立持久化（ex_mcstruct_ui），与 devMode 是「与」关系。 */
const EX_MCSTRUCT_UI_KEY = 'ex_mcstruct_ui';
let mcStructUiOn = false;
try { mcStructUiOn = localStorage.getItem(EX_MCSTRUCT_UI_KEY) === '1'; } catch (e) {}
function mcStructUiVisible() { return !!devMode && !!mcStructUiOn; }
function setMcStructUi(on) {
    mcStructUiOn = !!on;
    try { localStorage.setItem(EX_MCSTRUCT_UI_KEY, mcStructUiOn ? '1' : '0'); } catch (e) {}
    applyMcStructUiVisibility();
}
/* 入口是【动态生成】的（导出面板 / 导入面板每次打开都重建 DOM），
   所以既要在建好后立刻调一次，也要在开关切换时调一次。 */
function applyMcStructUiVisibility() {
    const on = mcStructUiVisible();
    const eb = document.getElementById('mcStructExportBtn');      // 导出面板：🧱 结构导出
    if (eb) eb.style.display = on ? '' : 'none';
    const sb = document.getElementById('importModeStruct');       // 导入面板：「结构」页签
    if (sb) sb.style.display = on ? '' : 'none';
    const fi = document.getElementById('mcStructFileInput');      // 导入面板的隐藏 file input
    if (fi && typeof fi.dataset.cmdAccept === 'string') {
        fi.accept = on ? (fi.dataset.cmdAccept + ',.mcstructure') : fi.dataset.cmdAccept;
    }
    const dz = document.getElementById('mcStructImportDropZone');
    if (dz && !on) {
        // 开关被关掉时若正停在「结构」页，退回「命令」页（结构区收起，不留半截面板）。
        // ★判据必须是「结构」页自身处于 active，而不是「命令页不 active」——否则会误伤「模型」页
        //   （OBJ 导入入口开启后可以让面板初始就停在「模型」页，旧判据会把它强拉回「命令」页）。
        const structBtn = document.getElementById('importModeStruct');
        const cmdBtn = document.getElementById('importModeCmd');
        if (structBtn && structBtn.classList.contains('active') && cmdBtn && typeof cmdBtn.onclick === 'function') cmdBtn.onclick();
    }
}

function makeDevItem(title, desc, onClick) {
    const row = document.createElement('div'); row.className = 'ui-settings-item';
    row.style.cssText = 'flex-direction:column;align-items:stretch;gap:8px;';
    const left = document.createElement('div');
    left.style.cssText = 'display:flex;flex-direction:column;gap:2px;';
    const t = document.createElement('span'); t.textContent = title; t.style.fontWeight = '600';
    const d = document.createElement('span'); d.textContent = desc; d.style.cssText = 'font-size:11px;opacity:.7;';
    left.appendChild(t); left.appendChild(d);
    const btn = document.createElement('button'); btn.type = 'button'; btn.className = 'prj-btn prj-btn-sm'; btn.textContent = '执行';
    btn.addEventListener('click', (e) => { e.stopPropagation(); onClick(); });
    row.appendChild(left); row.appendChild(btn);
    return row;
}

/* 开发者工具里的「开关型」条目（右侧是一个 .ui-checkbox，而不是「执行」按钮） */
function makeDevToggleItem(title, desc, getVal, setVal) {
    const row = document.createElement('div'); row.className = 'ui-settings-item';
    const left = document.createElement('div');
    left.style.cssText = 'display:flex;flex-direction:column;gap:2px;flex:1 1 auto;min-width:0;';
    const t = document.createElement('span'); t.textContent = title; t.style.fontWeight = '600';
    const d = document.createElement('span'); d.textContent = desc; d.style.cssText = 'font-size:11px;opacity:.7;';
    left.appendChild(t); left.appendChild(d);
    const cb = document.createElement('button');
    cb.type = 'button'; cb.className = 'ui-checkbox'; cb.id = 'mcStructUiCheckbox';
    const sync = () => {
        const on = !!getVal();
        cb.classList.toggle('checked', on);
        cb.setAttribute('aria-pressed', on ? 'true' : 'false');
    };
    cb.addEventListener('click', (e) => { e.stopPropagation(); setVal(!getVal()); sync(); });
    sync();
    row.appendChild(left); row.appendChild(cb);
    return row;
}

function ensureDevSettingEntry() {
    const sp = document.getElementById('uiSettingsPanel');
    if (!sp) return;
    if (document.getElementById('exDevSettingItem')) { try { refreshDevSettingEntry(); } catch (e) {} return; }
    const box = document.createElement('div');
    // collapsible + collapsed：开发者模式启用时列表默认折叠（点击标题栏展开，复用设置面板通用折叠机制）
    box.id = 'exDevSettingItem'; box.className = 'ui-settings-group collapsible collapsed ui-settings-cat-off'; box.setAttribute('data-group', 'dev'); box.setAttribute('data-cat', 'help');
    box.style.display = devMode ? '' : 'none';
    const head = document.createElement('div'); head.className = 'ui-settings-group-head';
    head.innerHTML = '<span>🛠 开发者工具</span>';
    const body = document.createElement('div'); body.className = 'ui-settings-group-body';
    // 彩蛋体：第一次展开列表时显示这张图（而不是选项），第二次展开才显示选项
    const eggBox = document.createElement('div');
    eggBox.className = 'ui-settings-group-body ex-dev-egg-body';
    eggBox.style.display = 'none';
    eggBox.innerHTML = '<img class="ex-dev-egg-img" src="data:image/jpeg;base64," alt="彩蛋">';
    // 折叠/展开时决定「显示彩蛋还是显示选项」。本监听挂在 head 上，先于设置面板的
    // 通用折叠委托（面板级监听在冒泡更外层）触发 —— 此刻 .collapsed 还没被切换，
    // 所以 box 带 .collapsed 即代表本次点击会【展开】。
    head.addEventListener('click', () => {
        const willExpand = box.classList.contains('collapsed');
        if (!willExpand) {
            // 收起：复位两个体的内联显示，交给 CSS（.collapsed 会隐藏 body）
            eggBox.style.display = 'none';
            body.style.display = '';
            return;
        }
        if (!devEggSeen()) {
            markDevEggSeen();               // 第一次展开：只显示彩蛋图
            eggBox.style.display = '';
            body.style.display = 'none';
        } else {
            eggBox.style.display = 'none';  // 之后展开：正常显示选项
            body.style.display = '';
        }
    });
    body.appendChild(makeDevItem('清除新手教程进度', '重置「已看完」记录，可重新体验新用户引导', () => {
        try { localStorage.removeItem(EX_TUT_KEY); localStorage.removeItem(EX_INTRO_KEY); } catch (e) {}
        tutAutoShown = false;
        showTutorialWelcome();
        showToast('已清除进度，重新向你展示新用户引导', { duration: 2600 });
    }));
    body.appendChild(makeDevItem('重播开场动画', '重新播放电影感运镜开场（约36秒，可点击跳过）', () => {
        try { playCinematicIntro(() => showToast('开场动画播放完毕', { duration: 1800 })); } catch (e) { showToast('当前环境无法播放开场动画', { duration: 2000 }); }
    }));
    body.appendChild(makeDevItem('立即重新弹出新手教程', '无视进度，直接打开教程章节目录', () => {
        tutAutoShown = true; openTutorialOverview();
    }));
    body.appendChild(makeDevItem('AI 对话', '打开 AI 建模对话窗口（实验性功能）', () => {
        try { aiChatToggle(true); } catch (e) { showToast('AI 对话不可用', { duration: 2000 }); }
    }));
    body.appendChild(makeDevItem('AI 服务设置', '配置云端 API / 本地模型，管理多服务与密钥', () => {
        try { aiSvcOpen(); } catch (e) { showToast('AI 服务面板不可用', { duration: 2000 }); }
    }));
    body.appendChild(makeDevToggleItem('显示 MC 结构导入 / 导出', '开启后：导出面板出现「🧱 结构导出」、导入面板出现「结构」页签（默认隐藏）',
        () => mcStructUiOn, (v) => setMcStructUi(v)));
    body.appendChild(makeDevItem('清除「OBJ 导入已开启」状态', 'OBJ 模型导入入口恢复默认关闭（导入面板「模型」页签重新隐藏）；可由「画笔模式 · 生成方块 · 长按三角形按钮」再次开启', () => {
        clearObjImportEnabled();
        showToast('已清除：OBJ 导入入口恢复默认关闭', { duration: 2400 });
    }));
    body.appendChild(makeDevItem('退出开发者模式', '隐藏本面板，恢复正常', () => {
        setDevMode(false);
        showToast('已退出开发者模式', { duration: 2000 });
    }));
    box.appendChild(head); box.appendChild(eggBox); box.appendChild(body);
    const scroll = sp.querySelector('.ui-settings-scroll');
    if (scroll) scroll.appendChild(box); else sp.appendChild(box);
    try { refreshDevSettingEntry(); } catch (e) {}
}

function refreshDevSettingEntry() {
    const box = document.getElementById('exDevSettingItem');
    if (box) box.style.display = devMode ? '' : 'none';
}

function setDevMode(on) {
    devMode = !!on;
    try { localStorage.setItem(EX_DEV_KEY, devMode ? '1' : '0'); } catch (e) {}
    // 启用（含解锁瞬间与刷新后从 localStorage 读出）时，开发者工具列表保持折叠
    const box = document.getElementById('exDevSettingItem');
    if (box) {
        if (devMode) box.classList.add('collapsed');
        else { box.classList.remove('collapsed');
            // 退出时复位彩蛋/选项的内联显示，并清空「已看过彩蛋」标记 ——
            // 这样【再次启用开发者模式】会重新触发彩蛋（按「启用周期」触发，不一次性失效）。
            try { localStorage.removeItem(EX_DEV_EGG_KEY); } catch (e) {}
            const egg = box.querySelector('.ex-dev-egg-body');
            const opt = box.querySelector('.ui-settings-group-body:not(.ex-dev-egg-body)');
            if (egg) egg.style.display = 'none';
            if (opt) opt.style.display = '';
        }
    }
    refreshDevSettingEntry();
    refreshAiEntryVisibility();
    try { applyMcStructUiVisibility(); } catch (e) {}   // MC 结构入口 = devMode && 开关
}

// AI 入口可见性：全部跟随开发者模式。退出时顺带收起已打开的面板，
// 避免「退出后仍浮着一个不可再打开的 AI 窗口」。
function refreshAiEntryVisibility() {
    // 顶栏不再有 AI 按钮（已移除）；AI 入口只存在于「设置 → 🛠 开发者工具」内。
    const svcEntry = document.getElementById('aiServiceManageBtn');
    if (svcEntry) {
        const row = svcEntry.closest('.ui-settings-item') || svcEntry;
        row.style.display = devMode ? '' : 'none';
    }
    if (!devMode) {
        try { const cp = document.querySelector('.ai-chat-panel'); if (cp && cp.style.display !== 'none') aiChatToggle(false); } catch (e) {}
        try { const sp = document.getElementById('aiServicePanel'); if (sp) sp.style.display = 'none'; } catch (e) {}
    }
}

// 彩蛋：更新日志里同一条目完整「展开→收起」满 3 轮（连续 6 击）→ 解锁开发者模式
function devChangelogClick(target) {
    const now = Date.now();
    // 计轮口径：本函数在标题点击后、状态切换前调用 —— 此刻 body 仍带 .open 即代表
    // 本次点击会把它收起，等于完成一轮完整「开关」（展开+收起）。3 轮 = 连续 6 次点击。
    // 只数「收起」动作而不是裸点数，避免「开→关→开」才 1.5 轮就被误判成 3 次。
    const body = target ? document.getElementById(target) : null;
    const willClose = !!(body && body.classList.contains('open'));
    if (target && target === _clTarget && (now - _clTime) < 1500) {
        _clTime = now;                        // 滑动窗口：每次命中刷新计时
        if (willClose) _clCycles++;
    } else {
        _clTarget = target;
        _clTime = now;
        _clCycles = willClose ? 1 : 0;        // 换条目 / 超时 → 重新计轮（首击即收起也算 1 轮）
    }
    if (_clCycles >= 3) {
        _clTarget = null; _clTime = 0; _clCycles = 0;
        if (!devMode) { setDevMode(true); showToast('🛠 开发者模式已解锁：设置里出现了「开发者工具」', { duration: 3200 }); }
        else { showToast('开发者模式已处于开启状态', { duration: 1800 }); }
        return true;
    }
    return false;
}

