function tutPollStart() { tutClearPoll(); tutTimer = setInterval(tutTick, 450); }
// 页面加载即把「新手教程」入口挂到设置面板顶部（settings 面板是静态 HTML，已存在于 DOM）
try { ensureTutorialSettingEntry(); } catch (e) {}
// 开发者工具入口：默认隐藏，靠更新日志彩蛋解锁后才显示
try { injectDevStyle(); ensureDevSettingEntry(); } catch (e) {}
// AI 全部入口一律收进开发者模式（默认不可见）
