// ESC 统一处理（按优先级从上到下依次尝试，命中即返回）：
//   ① 关闭关键帧（窗口 → 关键帧模式），不退出项目；
//   ② 在项目内则自动保存并退出项目；若进入 ESC 时处于全屏，退出项目后再退出全屏；
//   ③ 以上都不适用时，才退出全屏。
document.addEventListener('keydown', (e) => {
    if (e.key !== 'Escape') return;
    // 镜像进行中：Esc 只取消镜像（不退出模式/项目）
    if (mirrorActive) { e.preventDefault(); mirrorExit(true); return; }
    // ① 关键帧优先：窗口开着先关窗口（不退出关键帧模式）；仅剩关键帧模式时再退模式。两种情况都【不】退出项目。
    //   ★【2026-10-20】原实现「关窗口的同时顺手 exitKeyframeMode()」⇒ 用户按 Esc 只想收起浮动窗，
    //   结果整个关键帧模式被退出、侧栏时间表一起消失（与浮动窗 ✕ 同源的投诉）。现与 ✕ 统一口径：
    //   一次 Esc 只收起浮动窗，想退出关键帧模式再按一次（符合本处理器「依次尝试、命中即返回」的设计）。
    if (keyframeWindowOpen && keyframeWindowEl) {
        if (typeof closeKeyframeWindow === 'function') closeKeyframeWindow();
        else { keyframeWindowEl.style.display = 'none'; keyframeWindowOpen = false; }   // 收窗不停播放（与 closeKeyframeWindow 同口径）
        return;
    }
    if (isKeyframeMode) {
        try { exitKeyframeMode(); } catch (_) {}
        return;
    }
    // 正在编辑输入框：交给原生 ESC（不抢）
    const ae = document.activeElement;
    if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.isContentEditable)) return;
    // ② 自动保存并退出项目（优先级高于退出全屏）：仅当在项目内且无弹窗时执行，避免误退
    if (document.body.classList.contains('in-simulator') && !document.querySelector('.modal')
        && currentProjectId && typeof backToProjectList === 'function') {
        if (window.__exaSettingsOpen) { try { toggleUISettingsPanel(); } catch (_) {} } // 收起可能残留的设置面板浮层
        // 记录进入 ESC 瞬间是否处于全屏；全屏下要在「保存+退出项目」之后再退出全屏
        const fsActiveBefore = !!(document.fullscreenElement || window._isFullscreen);
        Promise.resolve(backToProjectList()).then(() => {
            if (typeof showToast === 'function') showToast('已自动保存并退出项目', { duration: 2200 });
            // 此前处于全屏：先完成保存+退出项目，再退出全屏。
            // 仍处全屏才执行，避免 Web 原生全屏已被 ESC 自动退出后误重新进入全屏。
            if (fsActiveBefore && (document.fullscreenElement || window._isFullscreen)) {
                try { toggleFullscreen(); } catch (_) {}
            }
        });
        return;
    }
    // ③ 其次：退出全屏（不在项目内 / 有弹窗时，ESC 才用来退出全屏）
    if (document.fullscreenElement || window._isFullscreen) {
        try { toggleFullscreen(); } catch (_) {}
    }
});

